const hex=v=>typeof v==='string'&&/^[a-f0-9]{64}$/.test(v),rev=v=>typeof v==='string'&&v.trim().length>0;
export function valid(s,meta,m,safe){if(!s||!meta||!m||!['1F','2F'].includes(s.floor)||!Array.isArray(s.foot)||s.foot.length!==2||!s.foot.every(Number.isInteger)||!rev(meta.revision)||!rev(m.revision)||meta.revision!==m.revision||!hex(meta.sourceSHA)||!hex(m.floors?.[s.floor]?.sourceSHA)||meta.sourceSHA!==m.floors[s.floor].sourceSHA||meta.verified!==true||meta.enabled!==true||!(safe instanceof Uint8Array)||safe.length!==696*464)return false;const[x,y]=s.foot;return x>=0&&y>=0&&x<696&&y<464&&safe[y*696+x]!==0;}
export function step(s,dx,dy,meta,m,safe){if(!valid(s,meta,m,safe)||![dx,dy].every(Number.isInteger)||Math.abs(dx)+Math.abs(dy)!==1)return s;const[x,y]=s.foot,X=x+dx,Y=y+dy;if(X<0||Y<0||X>=696||Y>=464||!safe[Y*696+X])return s;return{...s,foot:[X,Y]};}
export function transfer(s,meta,m,safe,targetSafe){if(!valid(s,meta,m,safe)||!(targetSafe instanceof Uint8Array)||targetSafe.length!==696*464)return s;const f=m.floors[s.floor],end=f.endpoint;if(!Array.isArray(end)||s.foot[0]!==end[0]||s.foot[1]!==end[1])return s;const target=s.floor==='1F'?'2F':'1F',t=m.floors[target],a=t?.arrival,tr=t?.trigger;if(!Array.isArray(a)||a.length!==2||!a.every(Number.isInteger)||!Array.isArray(tr)||tr.length!==4||!tr.every(Number.isInteger)||!hex(t.sourceSHA))return s;const[x,y]=a;if(x<24||x>=672||y<18||y>=446||!targetSafe[y*696+x]||!(x+24<tr[0]||x-24>tr[2]||y+18<tr[1]||y-18>tr[3]))return s;return{floor:target,foot:[x,y],transfers:(s.transfers??0)+1};}
